effects.source:
useCallback((next: Session | null) => {
    setSession(next)
    write(next)
  }, [])

useCallback(
    async ({ fullName, email, organization, provider = 'password' }: SignUpInput) => {
      await latency()
      const next: Session = {
        user: {
          id: crypto.randomUUID(),
          fullName: fullName.trim(),
          email: email.trim().toLowerCase(),
          organization: organization?.trim() || null,
          provider,
        },
        onboarding: null,
      }
      persist(next)
      return next
    },
    [persist],
  )

useCallback(
    async ({ email, provider = 'password' }: { email: string; provider?: User['provider'] }) => {
      await latency()
      const existing = read()
      const next: Session = existing?.user.email === email.trim().toLowerCase()
        ? existing
        : {
            user: {
              id: crypto.randomUUID(),
              fullName: email.split('@')[0].replace(/[._-]+/g, ' '),
              email: email.trim().toLowerCase(),
              organization: null,
              provider,
            },
            onboarding: null,
          }
      persist(next)
      return next
    },
    [persist],
  )

useCallback(
    (profile: Omit<OnboardingProfile, 'completedAt'>) => {
      setSession((current) => {
        if (!current) return current
        const next: Session = {
          ...current,
          onboarding: { ...profile, completedAt: new Date().toISOString() },
        }
        write(next)
        return next
      })
    },
    [],
  )

